{
  "vulnerable_symbols": [
    "yaml.load",
    "yaml.full_load"
  ],
  "trigger": "应用使用 PyYAML 5.3.1 的 yaml.load/FullLoader 或 yaml.full_load 解析攻击者可控 YAML，且 YAML 含 !!python/object/new 等危险标签。",
  "preconditions": [],
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "EIP currently links 5 repository PoCs, 6 curated repository PoCs, and 2 lab environments to CVE-2020-14343."
    },
    {
      "src": 1,
      "kind": "poc",
      "quote": "The /parse endpoint accepts YAML input and processes it using PyYAML's FullLoader, which is vulnerable to arbitrary code execution via specially crafted YAML tags (e.g., !!python/object/new)."
    },
    {
      "src": 2,
      "kind": "poc",
      "quote": "PyYAML 在使用 yaml.load() 解析不可信数据时,未限制危险的 YAML 标签(如 !!python/object),攻击者可构造恶意 YAML 内容执行任意 Python 代码。"
    }
  ],
  "fixed_version": "5.4",
  "summary_zh": "PyYAML 5.3.1 的 FullLoader 解析不可信 YAML 可致 RCE，升级 5.4 或改用 safe_load。"
}
